messages.source:
.local $n1 = {$num :number notation=scientific minimumSignificantDigits=5}
.local $n2 = {$num :number style=percent}
.local $n3 = {$num :number minimumIntegerDigits=4 minimumFractionDigits=4}
.local $n4 = {$num :number maximumSignificantDigits=6}
{{The number in scientific notation is {$n1}. As a percentage, it's {$n2}.
Formatted with at least four integer digits and four fractional digits, it's
{$n3}. Formatted with at most six significant digits, it's {$n4}.}}

translations.fr:
.local $n1 = {$num :number notation=scientific minimumSignificantDigits=5}
.local $n2 = {$num :number style=percent}
.local $n3 = {$num :number minimumIntegerDigits=4 minimumFractionDigits=4}
.local $n4 = {$num :number maximumSignificantDigits=6}
{{En notation scientifique : {$n1}. En pourcentage : {$n2}.
Avec au moins quatre chiffres entiers et quatre décimales : {$n3}.
Avec au plus six chiffres significatifs : {$n4}.}}

messages.source:
.input {$num :number select=ordinal}
.match $num
one {{You are {$num}st}}
two {{You are {$num}nd}}
few {{You are {$num}rd}}
* {{You are {$num}th}}

.input {$foo :string}
.input {$bar :string}
.match $foo $bar
* bar {{Any and bar}}
foo * {{Foo and any}}
foo bar {{Foo and bar}}
* * {{Otherwise}}

translations.fr:
.input {$foo :string}
.input {$bar :string}
.match $foo $bar
* bar {{Quelconque et bar}}
foo * {{Foo et quelconque}}
foo bar {{Foo et bar}}
* * {{Autre cas}}

